const names=['Maya','Arun','Leah'];
let lamp=localStorage.getItem('splitsync-lamp')||'Maya';
let published=localStorage.getItem('splitsync-published')==='true';
let stream=null;
const money=n=>'$'+Number(n).toFixed(2);
const shares=()=>Object.fromEntries(names.map(n=>[n,40+(n===lamp?30:0)]));
const badge='<span class="badge">Sandbox demo</span>';
const button=(t,d,c='primary')=>`<button class="${c}" onclick="go('${d}')">${t}</button>`;
const purchase=()=>`<div class="purchase"><div class="icon">⌂</div><div><h3>Move-in essentials</h3><small>Demo Merchant · Purchase SS-001</small></div></div>`;
const title=(e,t,s='',action='')=>`<div class="heading"><div><div class="eyebrow">${e}</div><h1>${t}</h1><p>${s}</p></div>${action}</div>`;
function go(p){location.hash=p}
function status(n){return n==='Maya'?'Paid':n==='Arun'?'Processing':'Awaiting payment'}
function people(withStatus=true){return names.map(n=>`<div class="row"><span class="person ${n.toLowerCase()}">${n[0]}</span><div class="grow"><b>${n}</b><small>${n===lamp?'Shared essentials + lamp':'Shared essentials'}</small></div><b>${money(shares()[n])}</b>${withStatus?`<span class="pill ${status(n).split(' ')[0].toLowerCase()}">${status(n)}</span>`:''}</div>`).join('')}
function receipt(){return `<div class="card receipt"><div class="section-title"><h2>Original bill</h2><span class="icon">▤</span></div>${purchase()}<div class="rule"></div><div class="row"><span>Shared kitchen essentials<small>Kitchen items, storage & cleaning</small></span><b>$120.00</b></div><div class="row"><span>Lamp<small>Personal item · ${lamp}</small></span><b>$30.00</b></div><div class="row total"><span>Total</span><span>$150.00 USD</span></div>${badge}</div>`}
function home(){return title('A little less admin','Good afternoon, Leah ☀','Your shared purchases, all in one place.',button('＋ New purchase','scan'))+`<section class="hero"><div><span class="eyebrow">A fresh start, together</span><h2>New place. Shared things.<br>One simple split.</h2><p>Scan the merchant QR, tell us who’s sharing, and let everyone pay their part.</p>${button('▣ &nbsp; Scan QR','scan')}</div><div class="hero-art"><div class="receipt-art">▤<small>Kitchen &nbsp; $120<br>Lamp &nbsp; &nbsp; $30<br>────────<br>Total &nbsp; &nbsp; $150</small></div></div></section><div class="stats"><div class="stat"><label>Active purchases</label><strong>01</strong><small>With your household</small></div><div class="stat"><label>Paid so far · Demo</label><strong>${money(shares().Maya)}</strong><small>Of $150.00 total</small></div><div class="stat"><label>People paid</label><strong>1 <span class="muted">/ 3</span></strong><small>One step closer to settled</small></div></div><div class="split-grid"><section><div class="section-title"><h2>Active shared purchases</h2><a href="#dashboard">View all ↗</a></div><div class="card">${purchase()}<div class="rule"></div><div class="row"><span class="sub">Purchase total ${badge}</span><b>$150.00 USD</b></div><div class="progress"><i style="width:${shares().Maya/150*100}%"></i></div><div class="row"><span class="sub">1 of 3 paid</span><span class="sub">${money(150-shares().Maya)} remaining</span></div>${button('View purchase →','dashboard','secondary full')}</div></section><section><div class="section-title"><h2>At a glance</h2><span class="sub">Move-in essentials</span></div><div class="card">${people()}<div class="note">✧ &nbsp; Everyone has their own payment link. Share once, track it all here.</div></div></section></div>`}
function scan(error=false){return title('01 / Start a shared purchase','Scan merchant QR','Point your camera at the merchant QR')+`<div class="split-grid"><div class="camera" id="camera">${error?'<div class="center" style="padding:25px;color:white"><h2>Camera unavailable</h2><p style="color:white">Allow camera access in your browser, or use a fallback below.</p></div>':'<div class="scanframe"><b>⌂<small>Demo Merchant<br>Move-in essentials</small><div style="font-size:50px">▦</div></b></div><div class="scanline"></div>'}</div><div class="card"><h2>One scan. Everyone included.</h2><p>Open a purchase from your merchant, review the bill, and prepare your group’s split.</p><div class="note">This walkthrough uses a sample merchant QR. Camera preview does not decode QR codes in this demo.</div><div class="actions"><button onclick="startCamera()">Enable camera</button>${button('Open demo purchase','review')}</div><label for="purchase-link">Or paste a merchant purchase link</label><input id="purchase-link" placeholder="Demo link: #purchase/SS-001"><div class="actions"><button class="secondary" onclick="pasteLink()">Open pasted link</button>${button('Permission denied state','scan-error','')}</div><p class="sub" id="scan-message" role="status"></p></div></div>`}
async function startCamera(){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const v=document.createElement('video');v.autoplay=true;v.playsInline=true;v.srcObject=stream;v.style.cssText='width:100%;height:330px;object-fit:cover;border-radius:15px';document.querySelector('#camera').replaceChildren(v)}catch{go('scan-error')}}
function pasteLink(){const s=document.querySelector('#purchase-link').value;if(s.includes('#purchase/SS-001'))go('review');else document.querySelector('#scan-message').textContent='Unsupported code or link. Use the demo purchase link above or open the demo purchase.'}
function review(){return title('02 / Purchase details','A new place starts here.','Check the bill before preparing your split.')+`<div class="split-grid">${receipt()}<div class="card"><h2>Who’s sharing?</h2>${people(false)}<label for="instruction">Split instruction</label><textarea id="instruction" rows="4">Split the $120 kitchen essentials evenly between Maya, Arun and Leah. The $30 lamp is for Maya.</textarea><div class="note">✧ Demo allocation uses the shared essentials rule. Choose who pays for the lamp on the next screen.</div><div class="actions">${button('Back','scan','secondary')}<button class="primary" onclick="prepare()">Prepare AI split →</button></div></div></div>`}
function prepare(){go(document.querySelector('#instruction').value.toLowerCase().includes('maya')?'split':'clarify')}
function split(clarify=false,edit=false){return title('03 / AI split review',clarify?'A quick clarification.':'A fair split, ready to review.','$150.00 allocated · Shared kitchen essentials split evenly.')+`<div class="split-grid">${receipt()}<div class="card"><div class="section-title"><h2>${edit?'Edit allocations':'Suggested allocations'}</h2><span class="badge">✧ AI assisted demo</span></div>${clarify||edit?`<label for="lamp">Who should pay for the lamp?</label><select id="lamp" onchange="setLamp(this.value)">${names.map(n=>`<option ${n===lamp?'selected':''}>${n}</option>`).join('')}</select><p class="sub">Everyone pays $40 for shared essentials. The selected person also pays $30 for the lamp.</p>`:''}${names.map(n=>`<div class="allocation"><details ${n===lamp?'open':''}><summary class="row"><span class="person ${n.toLowerCase()}">${n[0]}</span><b class="grow">${n}</b><b style="color:var(--purple)">${money(shares()[n])}</b><span>⌄</span></summary><div class="row sub"><span>Shared essentials (1 of 3)</span><span>$40.00</span></div>${n===lamp?'<div class="row sub"><span>Personal lamp</span><span>$30.00</span></div>':''}</details></div>`).join('')}<div class="note">✧ &nbsp; $120 shared essentials ÷ 3 = $40 each${lamp==='Maya'?' + $30 lamp for Maya':` + $30 lamp for ${lamp}`}. Review the amounts before publishing payment requests.</div><div class="actions">${button(edit||clarify?'Back to review':'Edit split',edit||clarify?'split':'edit','secondary')}<button class="primary" onclick="confirmSplit()">Confirm split →</button></div></div></div>`}
function setLamp(n){lamp=n;localStorage.setItem('splitsync-lamp',n);render()}
function confirmSplit(){published=true;localStorage.setItem('splitsync-published','true');go('requests')}
async function copyLink(n){const url=location.href.split('#')[0]+'#share/'+n.toLowerCase();try{await navigator.clipboard.writeText(url);toast(n+'’s link copied')}catch{prompt('Copy '+n+'’s payment link',url)}}
function requests(qr){return title('04 / Payment requests','Ready to share.','Each person gets a link to their own share.')+`<div class="split-grid"><div class="card">${purchase()}<div class="rule"></div>${names.map(n=>`<div class="row"><span class="person ${n.toLowerCase()}">${n[0]}</span><div class="grow"><b>${n}</b><small>${money(shares()[n])} USD · Sandbox demo</small></div><button onclick="copyLink('${n}')">Copy link</button><button onclick="go('qr/${n.toLowerCase()}')" aria-label="Show ${n}'s QR">▣</button></div>`).join('')}<div class="actions">${button('Track group payment','dashboard')}</div></div><div class="card center">${qr?`<div class="eyebrow">Payment link</div><h2>${qr} · ${money(shares()[qr])} USD</h2>${badge}<div class="qr" id="qr"></div><p>Scan to review ${qr}’s share.</p>${button('Open '+qr+'’s share','share/'+qr.toLowerCase(),'secondary')}`:'<div class="result-icon">↗</div><h2>One link per person.</h2><p>Share privately with each participant. Their page shows their own breakdown and payment summary.</p><div class="note">Demo links are browser routes, not secure private tokens. Production payment links require a backend.</div>'}</div></div>`}
function dashboard(){return title('Your shared purchase','Move-in essentials','Demo Merchant · SS-001',button('Share requests','requests','secondary'))+`<div class="split-grid">${receipt()}<div><div class="card"><div class="section-title"><h2>Group payment</h2>${badge}</div><div style="font-size:38px;font-weight:800;letter-spacing:-2px">${money(shares().Maya)} <span style="font-size:16px;letter-spacing:0;color:var(--muted)">/ $150.00 paid</span></div><div class="progress"><i style="width:${shares().Maya/150*100}%"></i></div><div class="row sub"><span>1 of 3 paid</span><span>${money(150-shares().Maya)} remaining</span></div>${people()}<div class="note">Processing payments are counted as paid only after confirmation. These statuses are sample data.</div></div><div class="card" style="margin-top:20px"><h3>${published?'Confirmed allocations':'Sample confirmed allocations'}</h3><p class="sub">$120 shared equally. ${lamp} pays for the $30 lamp.</p>${button('Review allocations','split','secondary full')}</div></div></div>`}
function share(n){const amount=shares()[n];return title('A shared purchase, made simple',`Your share · ${money(amount)} USD`,`Hi ${n}, here’s your part of the purchase.`)+`<div class="split-grid"><div class="card">${purchase()}<div class="rule"></div><h2>Your items</h2><div class="row"><span class="icon">♧</span><div class="grow"><b>Shared essentials <span class="sub">(1 of 3)</span></b><small>Kitchen items, storage & cleaning</small></div><b>$40.00</b></div>${n===lamp?'<div class="row"><span class="icon">♙</span><div class="grow"><b>Lamp</b><small>Your personal desk lamp</small></div><b>$30.00</b></div>':''}<div class="note">You’re paying only your share of the $150.00 purchase.</div></div><div class="card payment-summary"><h2>Payment summary</h2><div class="row"><span>Your share</span><b>${money(amount)}</b></div><div class="rule"></div><div class="row total"><span>Total to pay</span><span>${money(amount)} USD</span></div><div style="margin:12px 0 22px">${badge}</div>${button('<em>ᴘ</em> Pay with PayPal','handoff/'+n.toLowerCase(),'paypal full')}<p class="center sub">Continue in PayPal Sandbox.<br>This demo previews the handoff; it does not create a PayPal order.</p></div></div>`}
function handoff(n){return `<div class="narrow card center" style="border-top:5px solid #0070ba"><div style="color:#003087;font-size:34px;font-style:italic;font-weight:800">PayPal</div><h1>Continue in PayPal Sandbox</h1><p>${n} · ${money(shares()[n])} USD · Demo Merchant</p>${badge}<p>In the connected app, PayPal opens its own buyer sign-in and approval screen. This storyboard lets you preview each result without signing in.</p><div class="tabs" style="justify-content:center">${['Processing','Paid','Cancelled'].map(s=>button('Preview '+s,'result/'+n.toLowerCase()+'/'+s.toLowerCase(),s==='Paid'?'primary':'')).join('')}</div>${button('Return to your share','share/'+n.toLowerCase(),'secondary')}</div>`}
function result(n,s){const paid=s==='paid',cancel=s==='cancelled';return `<div class="narrow"><div class="tabs" aria-label="Demo result variants">${['processing','paid','cancelled'].map(v=>button(v[0].toUpperCase()+v.slice(1),'result/'+n.toLowerCase()+'/'+v,v===s?'selected':'')).join('')}</div><div class="card center"><div class="result-icon" style="${paid?'':cancel?'background:#fff0e9;color:#bd7852':'background:#f0ebff;color:#683cf0'}">${paid?'✓':cancel?'↶':'◷'}</div><div class="eyebrow">Sandbox demo</div><h1>${paid?'Payment complete':cancel?'Payment cancelled':'Payment processing'}</h1><p>${paid?'Demo payment recorded':cancel?'No payment was completed. You can return to your share and try again.':'Confirmation is pending. Your group’s ledger will update after confirmation.'}</p><h2>${money(shares()[n])} USD</h2><p>Move-in essentials · Demo Merchant</p><div class="card" style="text-align:left;background:#faf9fd"><div class="row"><span class="sub">Participant</span><b>${n}</b></div><div class="row"><span class="sub">Status</span><span class="pill ${paid?'paid':cancel?'awaiting':'processing'}">${s[0].toUpperCase()+s.slice(1)}</span></div>${paid?'<div class="row"><span class="sub">Receipt reference</span><b>DEMO-SS-8F3D21</b></div>':''}</div><div class="actions">${button(cancel?'Return to share & retry':'View your share','share/'+n.toLowerCase())}</div><p class="sub">Only your own payment details are shown on this link.</p></div></div>`}
function rent(){return title('Your household','Rent, with room to review.','A separate monthly workflow. No rent payments are initiated in this demo.')+`<div class="split-grid"><div class="card"><span class="badge">Draft · December 2026</span><h1>$2,400.00 USD</h1><p>Due December 1 · Sandbox demo</p><div class="rule"></div>${names.map(n=>`<div class="row"><b>${n}</b><span>$800.00</span><span class="pill awaiting">Draft</span></div>`).join('')}<div class="note">Saved rule: split rent equally among Maya, Arun and Leah. Each new month starts as a draft for organizer review.</div><button class="primary full" style="margin-top:20px" onclick="toast('December draft reviewed. Demo only; no rent requests sent.')">Review monthly draft</button></div><div class="card"><h2>Household rules</h2><p>The new place · 3 household members</p><div class="row"><b>Monthly rent</b><span>$2,400.00</span></div><div class="row"><b>Split method</b><span>Equal · 3 ways</span></div><div class="row"><b>Tracked separately</b><span class="pill awaiting">Not requested</span></div></div></div>`}
function shop(detail=false){return title('Good things, shared','Make the new place yours.','A small shortlist for your shared kitchen.',button('Shopping preferences','preferences','secondary'))+(detail?`<div class="split-grid"><div class="product" style="height:330px">♙</div><div class="card"><span class="eyebrow">Demo Merchant</span><h1>Move-in kitchen essentials</h1><h2>$120.00 USD</h2>${badge}<p>Cookware, storage and cleaning basics for your shared home. Add the demo bundle to the existing purchase to review its split with Maya’s $30 lamp.</p>${button('Add to shared purchase','review')}</div></div>`:`<div class="split-grid"><div class="card"><div class="product">♧</div><span class="sub">Demo Merchant · Sandbox demo</span><h2 style="margin:12px 0">Kitchen essentials bundle</h2><div class="row"><b>$120.00</b>${button('View demo item','product','secondary')}</div></div><div class="card"><div class="product" style="background:#ede7fa">♙</div><span class="sub">IKEA · External retailer</span><h2 style="margin:12px 0">Find furniture for your place</h2><p>Browse current products and prices at the retailer.</p><a href="https://www.ikea.com/" target="_blank" rel="noopener"><button class="secondary full">View at retailer ↗</button></a></div></div>`)}
function preferences(){return title('Make it your own','What’s on your list?','Optional interests for your household.')+`<div class="narrow card"><h2>Shopping preferences</h2>${['Kitchen','Furniture','Move-in essentials'].map(n=>`<label class="row" style="justify-content:flex-start"><input type="checkbox" style="width:20px" value="${n}" ${JSON.parse(localStorage.getItem('splitsync-interests')||'[]').includes(n)?'checked':''}>${n}</label>`).join('')}<div class="actions">${button('Skip','shop','secondary')}<button class="primary" onclick="localStorage.setItem('splitsync-interests',JSON.stringify([...document.querySelectorAll('input:checked')].map(i=>i.value)));go('shop')">Save preferences</button></div></div>`}
function welcome(){return `<div class="narrow card center"><div class="result-icon" style="color:var(--purple);background:var(--soft)">↗</div><div class="eyebrow">Welcome to SplitSync AI</div><h1>Split shared purchases<br>and see who’s paid.</h1><p>From the merchant’s QR to the last payment.<br>A little less admin, a little more together.</p>${button('Continue as demo organizer →','home','primary full')}<p class="sub">Sandbox demo · Sample data only</p></div>`}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3500)}
async function render(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}let [page,a,b]=location.hash.slice(1).split('/');page=page||'home';let n=names.find(n=>n.toLowerCase()===a)||'Maya';document.body.dataset.page=page;document.body.classList.toggle('payer',['share','handoff','result'].includes(page));document.querySelector('#breadcrumb').textContent=['share','handoff','result'].includes(page)?'↗ SplitSync AI':'Your workspace / '+({home:'Overview',dashboard:'Shared purchases',scan:'Scan QR',split:'AI split review'}[page]||'Shared purchases');document.querySelectorAll('nav a').forEach(x=>x.classList.toggle('active',x.hash==='#'+page));const views={home, welcome,scan:()=>scan(), 'scan-error':()=>scan(true),review,split:()=>split(),clarify:()=>split(true),edit:()=>split(false,true),requests:()=>requests(),qr:()=>requests(n),dashboard,share:()=>share(n),handoff:()=>handoff(n),result:()=>result(n,['paid','cancelled','processing'].includes(b)?b:'processing'),rent,shop:()=>shop(),product:()=>shop(true),preferences};document.querySelector('#app').innerHTML=(views[page]||home)();window.scrollTo(0,0);if(page==='qr'){const url=location.href.split('#')[0]+'#share/'+n.toLowerCase();const {default:QR}=await import('./qrcode.js');document.querySelector('#qr').innerHTML=QR(url)}}
window.addEventListener('hashchange',render);render();
